window.addEventListener('load', function() {

let toggleButton=document.querySelector(".header__action--dark-mode"),icon=toggleButton.querySelector("i"),body=document.body;function enableDarkMode(){body.classList.add("dark-mode"),icon.classList.replace("fa-moon","fa-sun"),localStorage.setItem("dark-mode","enabled")}function disableDarkMode(){body.classList.remove("dark-mode"),icon.classList.replace("fa-sun","fa-moon"),localStorage.setItem("dark-mode","disabled")}"enabled"===localStorage.getItem("dark-mode")&&enableDarkMode(),toggleButton.addEventListener("click",()=>{(body.classList.contains("dark-mode")?disableDarkMode:enableDarkMode)()});
});